//! Singer CSD (read only, spec-derived). An 8-byte identifier, then every byte is obfuscated
//! with two masks generated by the classic C `rand` linear congruential generator
//! (`seed = seed × 0x41C64E6D + 0x3039`, mask byte = bits 16–23): 479 subtracted bytes, then
//! 501 XOR bytes. A byte at file offset `o` decodes as `(b ^ xor[k % 501]) − sub[k % 479]`
//! with `k = o` ("type 0": seed 12, chosen when the identifier starts `7C` or has `C3` at
//! byte 2) or, for "type 1" (seed = identifier byte 0), `k` with its low byte remapped through
//! a 256-entry table and special cases at 0x100 / 0x200 modulo 0x300. (libembroidery passes
//! the stream position after reading the byte and subtracts one: the byte's own offset. An
//! earlier reading used `o − 1` and turned PE-DESIGN's CSD into noise, issue #135.)
//!
//! Decoded content: 16 RGB colours, 2 unknown bytes, 14 colour-order bytes (palette index per
//! colour block), then 3-byte records `flags, dy, dx` in 0.1 mm with y up: `dy` and `dx` are
//! magnitudes (0–255), flags bit 0x20 / 0x40 negate x / y; low 5 bits 0 = stitch, any of 0x0C
//! = colour stop (its bytes do not move the needle), others = trim with a move; `F8`, `87` or
//! `91` ends the design. Checked against PE-DESIGN 11.50's own CSD export
//! (`tests/fixtures/pe11/sample-basic.csd`): every needle point equals its DST export of the
//! same design, the palette starts with PE's 800 RED (E3 31 1F) and Prussian Blue, and the
//! colour order is 0, 1, ….
//!
//! Source: libembroidery `src/formats/singer.c` (`BuildDecryptionTable`, `DecodeCsdByte`,
//! `readCsd`; zlib licence, first published under MIT in Embroidermodder in 2013); the offset
//! table is copied from its `csd_decryptArray`. Type 1 is still checked only by synthetic
//! files. libembroidery has no writer and the unknown bytes are not described, so OpenStitch
//! does not write CSD.

use crate::{FormatError, Result};
use openstitch_core::{Command, Stitch, StitchPattern, Thread};

const SUB_MASK: usize = 479;
const XOR_MASK: usize = 501;

/// The two obfuscation masks for `seed`.
pub(crate) fn masks(seed: u32) -> (Vec<u8>, Vec<u8>) {
    let mut seed = seed;
    let mut next = || {
        seed = seed.wrapping_mul(0x41C6_4E6D).wrapping_add(0x3039);
        (seed >> 16) as u8
    };
    let sub = (0..SUB_MASK).map(|_| next()).collect();
    let xor = (0..XOR_MASK).map(|_| next()).collect();
    (sub, xor)
}

/// The mask index for the byte at `offset` (type 1 remaps the low byte).
pub(crate) fn mask_index(offset: usize, type1: bool) -> usize {
    let k = offset;
    if !type1 {
        return k;
    }
    let mut high = k & !0xFF;
    let low = k & 0xFF;
    match high % 0x300 {
        0x200 if low == 0 => high -= 0x100,
        0x100 if low <= 1 => high -= 0x100,
        _ => {}
    }
    usize::from(OFFSET_TABLE[low]) | high
}

pub fn read(data: &[u8]) -> Result<StitchPattern> {
    let Some(id) = data.get(..8) else {
        return Err(FormatError::Truncated("CSD identifier".into()));
    };
    let type1 = id[0] != 0x7C && id[2] != 0xC3;
    let (sub, xor) = masks(if type1 { u32::from(id[0]) } else { 0x0C });
    let decode = |offset: usize| -> Result<u8> {
        let b = *data
            .get(offset)
            .ok_or_else(|| FormatError::Truncated(format!("CSD at byte {offset}")))?;
        let k = mask_index(offset, type1);
        Ok((b ^ xor[k % XOR_MASK]).wrapping_sub(sub[k % SUB_MASK]))
    };
    let mut at = 8;
    let mut palette = Vec::with_capacity(16);
    for _ in 0..16 {
        let (r, g, b) = (decode(at)?, decode(at + 1)?, decode(at + 2)?);
        palette.push(Thread::rgb(
            u32::from(r) << 16 | u32::from(g) << 8 | u32::from(b),
        ));
        at += 3;
    }
    at += 2; // unknown
    let mut order = [0_u8; 14];
    for o in &mut order {
        *o = decode(at)?;
        at += 1;
    }
    let thread_for = |block: usize| palette[usize::from(order[block % 14]) % 16].clone();

    let mut pattern = StitchPattern::new();
    pattern.threads.push(thread_for(0));
    let (mut x, mut y) = (0.0_f64, 0.0_f64);
    while at + 3 <= data.len() {
        let (b0, b1, b2) = (decode(at)?, decode(at + 1)?, decode(at + 2)?);
        at += 3;
        if matches!(b0, 0xF8 | 0x87 | 0x91) {
            break;
        }
        // Magnitudes: libembroidery reads them as unsigned and takes the sign from the flags.
        let mut dx = f64::from(b2);
        let mut dy = f64::from(b1);
        if b0 & 0x20 != 0 {
            dx = -dx;
        }
        if b0 & 0x40 != 0 {
            dy = -dy;
        }
        let flags = b0 & 0x1F;
        if flags == 0 {
            x += dx;
            y -= dy;
            pattern.stitches.push(Stitch::new(x, y, Command::Stitch));
        } else if flags & 0x0C != 0 {
            // A stop before anything is sewn selects the first colour.
            if pattern.count(Command::Stitch) > 0 {
                pattern
                    .stitches
                    .push(Stitch::new(x, y, Command::ColorChange));
                let block = pattern.threads.len();
                pattern.threads.push(thread_for(block));
            }
        } else {
            pattern.stitches.push(Stitch::new(x, y, Command::Trim));
            if dx != 0.0 || dy != 0.0 {
                x += dx;
                y -= dy;
                pattern.stitches.push(Stitch::new(x, y, Command::Jump));
            }
        }
    }
    pattern.stitches.push(Stitch::new(x, y, Command::End));
    Ok(pattern)
}

